class DistanceLimitedPathsExist:

    def __init__(self, n: int, edgeList: List[List[int]]):
        parent = list(range(n))

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        self.adj = [[] for _ in range(n)]
        for u, v, d in sorted(edgeList, key=lambda e: e[2]):
            ru, rv = find(u), find(v)
            if ru != rv:
                parent[ru] = rv
                self.adj[u].append((v, d))
                self.adj[v].append((u, d))
        self.LOG = max(1, n.bit_length())
        self.up = [[-1] * n]
        self.heavy = [[0] * n]
        self.dep = [0] * n
        seen = [False] * n
        for s in range(n):
            if seen[s]:
                continue
            seen[s] = True
            stack = [s]
            while stack:
                u = stack.pop()
                for v, d in self.adj[u]:
                    if not seen[v]:
                        seen[v] = True
                        self.up[0][v] = u
                        self.heavy[0][v] = d
                        self.dep[v] = self.dep[u] + 1
                        stack.append(v)
        for k in range(1, self.LOG):
            pu, ph = self.up[k - 1], self.heavy[k - 1]
            cu, ch = [-1] * n, [0] * n
            for v in range(n):
                mid = pu[v]
                if mid != -1:
                    cu[v] = pu[mid]
                    ch[v] = max(ph[v], ph[mid])
            self.up.append(cu)
            self.heavy.append(ch)

    def query(self, p: int, q: int, limit: int) -> bool:
        if p == q:
            return True
        if self.dep[p] < self.dep[q]:
            p, q = q, p
        best = 0
        diff = self.dep[p] - self.dep[q]
        for k in range(self.LOG):
            if diff >> k & 1:
                best = max(best, self.heavy[k][p])
                p = self.up[k][p]
        if p == q:
            return best < limit
        for k in range(self.LOG - 1, -1, -1):
            a, b = self.up[k][p], self.up[k][q]
            if a != b and a != -1 and b != -1:
                best = max(best, self.heavy[k][p], self.heavy[k][q])
                p, q = a, b
        a, b = self.up[0][p], self.up[0][q]
        if a == -1 or b == -1 or a != b:
            return False
        return max(best, self.heavy[0][p], self.heavy[0][q]) < limit

