class DistanceLimitedPathsExist {
    int LOG;
    vector<vector<int>> up, heavy;
    vector<int> dep;

public:
    DistanceLimitedPathsExist(int n, vector<vector<int>>& edgeList) {
        vector<int> parent(n);
        iota(parent.begin(), parent.end(), 0);
        auto find = [&](int x) {
            while (parent[x] != x) { parent[x] = parent[parent[x]]; x = parent[x]; }
            return x;
        };
        sort(edgeList.begin(), edgeList.end(),
             [](const vector<int>& a, const vector<int>& b) { return a[2] < b[2]; });
        vector<vector<pair<int,int>>> adj(n);
        for (auto& e : edgeList) {
            int ru = find(e[0]), rv = find(e[1]);
            if (ru != rv) {
                parent[ru] = rv;
                adj[e[0]].push_back({e[1], e[2]});
                adj[e[1]].push_back({e[0], e[2]});
            }
        }
        LOG = 1;
        while ((1 << LOG) < n) ++LOG;
        up.assign(LOG, vector<int>(n, -1));
        heavy.assign(LOG, vector<int>(n, 0));
        dep.assign(n, 0);
        vector<char> seen(n, 0);
        for (int s = 0; s < n; ++s) {
            if (seen[s]) continue;
            seen[s] = 1;
            vector<int> stack{s};
            while (!stack.empty()) {
                int u = stack.back(); stack.pop_back();
                for (auto& [v, d] : adj[u])
                    if (!seen[v]) {
                        seen[v] = 1;
                        up[0][v] = u;
                        heavy[0][v] = d;
                        dep[v] = dep[u] + 1;
                        stack.push_back(v);
                    }
            }
        }
        for (int k = 1; k < LOG; ++k)
            for (int v = 0; v < n; ++v) {
                int mid = up[k - 1][v];
                if (mid != -1) {
                    up[k][v] = up[k - 1][mid];
                    heavy[k][v] = max(heavy[k - 1][v], heavy[k - 1][mid]);
                }
            }
    }

    bool query(int p, int q, int limit) {
        if (p == q) return true;
        if (dep[p] < dep[q]) swap(p, q);
        int best = 0;
        for (int diff = dep[p] - dep[q], k = 0; diff > 0; diff >>= 1, ++k)
            if (diff & 1) { best = max(best, heavy[k][p]); p = up[k][p]; }
        if (p == q) return best < limit;
        for (int k = LOG - 1; k >= 0; --k) {
            int a = up[k][p], b = up[k][q];
            if (a != b && a != -1 && b != -1) {
                best = max({best, heavy[k][p], heavy[k][q]});
                p = a;
                q = b;
            }
        }
        int ra = up[0][p], rb = up[0][q];
        if (ra == -1 || rb == -1 || ra != rb) return false;
        return max({best, heavy[0][p], heavy[0][q]}) < limit;
    }
};

