class DistanceLimitedPathsExist {
    private int LOG;
    private int[][] up, heavy;
    private int[] dep;

    public DistanceLimitedPathsExist(int n, int[][] edgeList) {
        int[] parent = new int[n];
        for (int i = 0; i < n; i++) parent[i] = i;
        Arrays.sort(edgeList, (a, b) -> Integer.compare(a[2], b[2]));
        List<int[]>[] adj = new List[n];
        for (int i = 0; i < n; i++) adj[i] = new ArrayList<>();
        for (int[] e : edgeList) {
            int ru = find(parent, e[0]), rv = find(parent, e[1]);
            if (ru != rv) {
                parent[ru] = rv;
                adj[e[0]].add(new int[]{e[1], e[2]});
                adj[e[1]].add(new int[]{e[0], e[2]});
            }
        }
        LOG = 1;
        while ((1 << LOG) < n) LOG++;
        up = new int[LOG][n];
        heavy = new int[LOG][n];
        for (int[] row : up) Arrays.fill(row, -1);
        dep = new int[n];
        boolean[] seen = new boolean[n];
        Deque<Integer> stack = new ArrayDeque<>();
        for (int s = 0; s < n; s++) {
            if (seen[s]) continue;
            seen[s] = true;
            stack.push(s);
            while (!stack.isEmpty()) {
                int u = stack.pop();
                for (int[] ed : adj[u]) {
                    int v = ed[0], d = ed[1];
                    if (!seen[v]) {
                        seen[v] = true;
                        up[0][v] = u;
                        heavy[0][v] = d;
                        dep[v] = dep[u] + 1;
                        stack.push(v);
                    }
                }
            }
        }
        for (int k = 1; k < LOG; k++)
            for (int v = 0; v < n; v++) {
                int mid = up[k - 1][v];
                if (mid != -1) {
                    up[k][v] = up[k - 1][mid];
                    heavy[k][v] = Math.max(heavy[k - 1][v], heavy[k - 1][mid]);
                }
            }
    }

    private int find(int[] parent, int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }

    public boolean query(int p, int q, int limit) {
        if (p == q) return true;
        if (dep[p] < dep[q]) { int t = p; p = q; q = t; }
        int best = 0;
        for (int diff = dep[p] - dep[q], k = 0; diff > 0; diff >>= 1, k++)
            if ((diff & 1) == 1) { best = Math.max(best, heavy[k][p]); p = up[k][p]; }
        if (p == q) return best < limit;
        for (int k = LOG - 1; k >= 0; k--) {
            int a = up[k][p], b = up[k][q];
            if (a != b && a != -1 && b != -1) {
                best = Math.max(best, Math.max(heavy[k][p], heavy[k][q]));
                p = a;
                q = b;
            }
        }
        int ra = up[0][p], rb = up[0][q];
        if (ra == -1 || rb == -1 || ra != rb) return false;
        return Math.max(best, Math.max(heavy[0][p], heavy[0][q])) < limit;
    }
}

